{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — maximize total profit (unit price minus raw material cost minus processing cost), or maximize total revenue (unit price only, ignoring costs)?"
  ],
  "rationale": "The response asks for a single policy choice between two mutually exclusive objective functions, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
