  "atomic_questions": [
    "Are there any demand limits (maximum number of units that can be sold) for each product, or can the factory produce and sell unlimited quantities of each product?"
  ],
  "rationale": "The response asks a single clarification question regarding whether demand limits exist or if quantities are unlimited. Although it presents two options, it requires a single policy choice/answer."
}

{
  "action": "question",
